import Foundation
public enum ServiceAccessZone:String,Codable,Sendable { case engineBay,underbody,cabin,wheelWell,trunk,bench,driveline,body }
public struct PhysicalPartServiceContract:Codable,Hashable,Sendable { public var specificationId:String,accessZone:ServiceAccessZone,primaryTool:String,measurement:String,verification:String; public init(specificationId:String,accessZone:ServiceAccessZone,primaryTool:String,measurement:String,verification:String){self.specificationId=specificationId;self.accessZone=accessZone;self.primaryTool=primaryTool;self.measurement=measurement;self.verification=verification} }
public enum PhysicalPartServiceAuthority {
    public static func infer(specificationId:String,family:String)->PhysicalPartServiceContract { let f=family.lowercased();let z:ServiceAccessZone = f.contains("brake")||f.contains("susp")||f.contains("wheel") ? .wheelWell : f.contains("trans")||f.contains("exhaust")||f.contains("driv") ? .underbody : f.contains("interior")||f.contains("electrical") ? .cabin : f.contains("body") ? .body : .engineBay;let tool = z == .wheelWell ? "torque wrench" : z == .underbody ? "lift + hand tools" : "hand tools";let measure = f.contains("bearing") ? "clearance/endplay" : f.contains("brake") ? "thickness/runout" : f.contains("engine") ? "clearance/pressure/temperature" : "condition/dimensions";return .init(specificationId:specificationId,accessZone:z,primaryTool:tool,measurement:measure,verification:"reassemble, torque/secure, function-test, record evidence") }
}
